using System;using System.IO;using System.Collections.Generic;
class ImportedMeaningChecks{static void Main(string[] args){try{var lex=Lexicon.Load(Path.Combine(args[0],"assets/dictionary.tsv.gz"));var meanings=Engine.Json.Deserialize<Dictionary<string,string>>(File.ReadAllText(Path.Combine(args[0],"assets/word-meanings.json")));foreach(var pair in meanings){var found=lex.Find(pair.Key);if(found==null||!found.Corrected||found.Meaning!=pair.Value)throw new Exception("Mismatch: "+pair.Key);}Console.WriteLine("PASS: "+meanings.Count+" imported definitions available for stale entries and shared dictionary lookup.");}catch(Exception e){Console.WriteLine(e);Environment.Exit(1);}}}
